declare module "*.css" {
	const source: string;
	export default source;
}

declare module "*.js" {
	const source: string;
	export default source;
}

declare module "*.html" {
	const source: string;
	export default source;
}

declare module "*.css?raw" {
	const source: string;
	export default source;
}

declare module "*.js?raw" {
	const source: string;
	export default source;
}

declare module "*.html?raw" {
	const source: string;
	export default source;
}
